draw:
var R = Math.min(H * 0.30, W * 0.13);
var groundY = H - 42;
var vRatio = p.spin;           // omega*R / v
var v = p.v;
var omegaR = v * vRatio;
var span = W - 2 * R - 20;
var travel = (v * 22 * t) % (span + 1);
var cx = R + 10 + travel;
var theta = (omegaR / R) * 22 * t;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// ground
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, groundY); ctx.lineTo(W, groundY); ctx.stroke();

// wheel
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.arc(cx, groundY - R, R, 0, Math.PI * 2); ctx.stroke();

// spokes so the rotation is visible
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
for (var k = 0; k < 6; k++) {
  var a = theta + k * Math.PI / 3;
  ctx.beginPath();
  ctx.moveTo(cx, groundY - R);
  ctx.lineTo(cx + R * Math.cos(a), groundY - R + R * Math.sin(a));
  ctx.stroke();
}
// paint mark on the rim
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(cx + R * Math.cos(theta + Math.PI / 2), groundY - R + R * Math.sin(theta + Math.PI / 2), 3.5, 0, Math.PI * 2);
ctx.fill();

// arrow helper
function arrow(x, y, dx, dy, col, lab) {
  if (Math.abs(dx) < 0.6 && Math.abs(dy) < 0.6) {
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI * 2); ctx.fill();
    ctx.fillText(lab, x + 6, y - 6);
    return;
  }
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.8;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + dx, y + dy); ctx.stroke();
  var ang = Math.atan2(dy, dx);
  ctx.beginPath();
  ctx.moveTo(x + dx, y + dy);
  ctx.lineTo(x + dx - 7 * Math.cos(ang - 0.4), y + dy - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x + dx - 7 * Math.cos(ang + 0.4), y + dy - 7 * Math.sin(ang + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.fillText(lab, x + dx + 5, y + dy - 4);
}

var sc = 5.0;
var vTop = v + omegaR;
var vBot = v - omegaR;
arrow(cx, groundY - 2 * R, vTop * sc, 0, C.accent, "top " + vTop.toFixed(1));
arrow(cx, groundY - R, v * sc, 0, C.figure, "center " + v.toFixed(1));
arrow(cx, groundY - 1, vBot * sc, 0, C.accent, "contact " + vBot.toFixed(1));

ctx.fillStyle = C.ink;
ctx.fillText("v = " + v.toFixed(1) + " m/s,  omega*R = " + omegaR.toFixed(1) + " m/s", 8, 16);
ctx.fillStyle = C.figure;
if (Math.abs(vBot) < 0.05) {
  ctx.fillText("rolling without slipping", 8, 32);
} else if (vBot > 0) {
  ctx.fillText("skidding forward: contact slides ahead", 8, 32);
} else {
  ctx.fillText("spinning too fast: contact slides backward", 8, 32);
}

out.note = "contact point velocity v - omegaR = " + vBot.toFixed(2) + " m/s; top of wheel " + vTop.toFixed(2) + " m/s";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = p.angle * Math.PI / 180;
var beta = p.beta;
var g = 9.8;

var pad = 26;
var baseY = H - 34;
var x0 = pad, x1 = W - pad;
var rise = Math.min((x1 - x0) * Math.tan(th), H - 70);
var run = rise / Math.tan(th);
var topX = x1 - run, topY = baseY - rise;

// incline
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.6;
ctx.beginPath();
ctx.moveTo(topX, topY); ctx.lineTo(x1, baseY); ctx.lineTo(topX, baseY); ctx.closePath();
ctx.stroke();
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, baseY); ctx.lineTo(W, baseY); ctx.stroke();

// ball sitting on the slope, two thirds of the way up
var f = 0.55;
var bx = x1 + (topX - x1) * f, by = baseY + (topY - baseY) * f;
var R = 22;
var nx = Math.sin(th), ny = -Math.cos(th);     // unit normal (screen coords, y down)
var ccx = bx + nx * R, ccy = by + ny * R;
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.arc(ccx, ccy, R, 0, Math.PI * 2); ctx.stroke();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ccx, ccy); ctx.lineTo(ccx + R * Math.cos(th), ccy - R * Math.sin(th)); ctx.stroke();

function arrow(x, y, dx, dy, col, lab, lx, ly) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.8;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + dx, y + dy); ctx.stroke();
  var a = Math.atan2(dy, dx);
  ctx.beginPath();
  ctx.moveTo(x + dx, y + dy);
  ctx.lineTo(x + dx - 7 * Math.cos(a - 0.4), y + dy - 7 * Math.sin(a - 0.4));
  ctx.lineTo(x + dx - 7 * Math.cos(a + 0.4), y + dy - 7 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.fillText(lab, x + dx + lx, y + dy + ly);
}

// weight
arrow(ccx, ccy, 0, 44, C.figure, "Mg", -8, 14);
// normal at the contact
arrow(bx, by, nx * 40, ny * 40, C.figure, "N", 4, -4);
// friction up the slope at the contact
var ux = (topX - x1) / Math.sqrt((topX - x1) * (topX - x1) + (topY - baseY) * (topY - baseY));
var uy = (topY - baseY) / Math.sqrt((topX - x1) * (topX - x1) + (topY - baseY) * (topY - baseY));
arrow(bx, by, ux * 38, uy * 38, C.accent, "f (static)", -46, 14);

// angle mark
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(x1, baseY, 26, Math.PI - th, Math.PI); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", x1 - 58, baseY - 6);

var a = g * Math.sin(th) / (1 + beta);
var fOverMg = beta * Math.sin(th) / (1 + beta);
var muMin = beta * Math.tan(th) / (1 + beta);

ctx.fillStyle = C.ink;
ctx.fillText("a = g sin" + "θ/(1+β) = " + a.toFixed(2) + " m/s²", 8, 16);
ctx.fillStyle = C.figure;
ctx.fillText("f = βMg sinθ/(1+β) = " + fOverMg.toFixed(3) + " Mg", 8, 32);

out.note = "β = " + beta.toFixed(2) + ": a = " + a.toFixed(2) + " m/s², friction needed = " + fOverMg.toFixed(3) + " Mg, minimum μs = " + muMin.toFixed(3);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = 9.8;
var th = p.angle * Math.PI / 180;
var pad = 26;
var baseY = H - 30;
var x1 = W - pad;
var rise = Math.min((x1 - pad) * Math.tan(th), H - 78);
var run = rise / Math.tan(th);
var topX = x1 - run, topY = baseY - rise;
var L = Math.sqrt(run * run + rise * rise);

ctx.strokeStyle = C.ink; ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.moveTo(topX, topY); ctx.lineTo(x1, baseY); ctx.stroke();
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, baseY); ctx.lineTo(W, baseY); ctx.stroke();

var ux = (x1 - topX) / L, uy = (baseY - topY) / L;
var nx = -uy, ny = ux;   // points away from the slope (upward-left in screen coords)

var shapes = [
  { b: 0.4,  name: "sphere  β=0.40" },
  { b: 0.5,  name: "disk    β=0.50" },
  { b: 1.0,  name: "hoop    β=1.00" }
];
// physical ramp length the reader imagines
var Lphys = p.length;
var slowest = Math.sqrt(2 * Lphys * (1 + 1.0) / (g * Math.sin(th)));
var cycle = slowest + 1.2;
var tt = t % cycle;

var lines = [];
for (var i = 0; i < shapes.length; i++) {
  var b = shapes[i].b;
  var acc = g * Math.sin(th) / (1 + b);
  var s = 0.5 * acc * tt * tt;
  var done = s >= Lphys;
  if (done) s = Lphys;
  var frac = s / Lphys;
  var R = 12;
  var px = topX + ux * frac * L + nx * R;
  var py = topY + uy * frac * L + ny * R;
  ctx.strokeStyle = (i === 0) ? C.accent : C.ink;
  ctx.lineWidth = (b === 1.0) ? 2.4 : 1.5;
  ctx.beginPath(); ctx.arc(px, py, R, 0, Math.PI * 2); ctx.stroke();
  if (b < 0.9) {
    var spin = -(s / R);
    ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(px, py);
    ctx.lineTo(px + R * Math.cos(spin), py + R * Math.sin(spin));
    ctx.stroke();
  }
  var vEnd = Math.sqrt(2 * g * Lphys * Math.sin(th) / (1 + b));
  lines.push(shapes[i].name + ": a = " + acc.toFixed(2) + " m/s², v_end = " + vEnd.toFixed(2) + " m/s");
}

ctx.fillStyle = C.ink;
for (var j = 0; j < lines.length; j++) {
  ctx.fillStyle = (j === 0) ? C.accent : C.figure;
  ctx.fillText(lines[j], 8, 16 + j * 15);
}

var vS = Math.sqrt(2 * g * Lphys * Math.sin(th) / 1.4);
var vH = Math.sqrt(2 * g * Lphys * Math.sin(th) / 2.0);
out.note = "sphere reaches the bottom at " + vS.toFixed(2) + " m/s, hoop at " + vH.toFixed(2) + " m/s: ratio " + (vS / vH).toFixed(4) + " no matter the angle or length";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = 9.8;
var v0 = p.v0, mu = p.mu, beta = 0.4;
var a = mu * g;
var tRoll = v0 / (a * (1 + 1 / beta));
var vRoll = v0 / (1 + beta);
var dRoll = (v0 * v0 - vRoll * vRoll) / (2 * a);

var padL = 44, padR = 14, padT = 26, padB = 30;
var tMax = tRoll * 1.7;
var vMax = v0 * 1.12;
function X(s) { return padL + (W - padL - padR) * (s / tMax); }
function Y(v) { return H - padB - (H - padT - padB) * (v / vMax); }

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, padT - 6); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("speed (m/s)", 4, padT - 12);
ctx.fillText("time (s)", W - padR - 48, H - 8);
ctx.fillText(v0.toFixed(0), padL - 22, Y(v0) + 4);
ctx.fillText("0", padL - 14, H - padB + 4);
ctx.fillText(tRoll.toFixed(2), X(tRoll) - 12, H - padB + 16);

// v(t) of the centre
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var s = tMax * i / 120;
  var v = (s < tRoll) ? v0 - a * s : vRoll;
  if (i === 0) ctx.moveTo(X(s), Y(v)); else ctx.lineTo(X(s), Y(v));
}
ctx.stroke();

// omega*R of the rim
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 120; k++) {
  var s2 = tMax * k / 120;
  var w = (s2 < tRoll) ? (a / beta) * s2 : vRoll;
  if (k === 0) ctx.moveTo(X(s2), Y(w)); else ctx.lineTo(X(s2), Y(w));
}
ctx.stroke();

// marker sweeping in time
var now = t % (tMax + 0.5);
if (now < tMax) {
  var vn = (now < tRoll) ? v0 - a * now : vRoll;
  var wn = (now < tRoll) ? (a / beta) * now : vRoll;
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(now), padT - 6); ctx.lineTo(X(now), H - padB); ctx.stroke();
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(X(now), Y(vn), 4, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(X(now), Y(wn), 4, 0, Math.PI * 2); ctx.fill();
}

// meeting point
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(padL, Y(vRoll)); ctx.lineTo(X(tRoll), Y(vRoll)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent; ctx.fillText("v of centre", X(tRoll) + 8, Y(v0 * 0.95));
ctx.fillStyle = C.figure;  ctx.fillText("ωR of rim", X(tRoll) + 8, Y(vRoll * 0.35));
ctx.fillStyle = C.ink;
ctx.fillText("they meet at " + vRoll.toFixed(2) + " m/s", X(tRoll) + 8, Y(vRoll) - 8);

out.note = "rolling starts at t = " + tRoll.toFixed(2) + " s and v = " + vRoll.toFixed(2) + " m/s, after sliding " + dRoll.toFixed(2) + " m";
